from content1 import put
# ---------------- 2 unpruuf Compliance ----------------
put("2_safeline","EN","unpruuf Compliance","unpruuf Compliance · reporting channel for companies and institutions · status 12 Oct 2026",[
("What it is",[("p","unpruuf Compliance is a channel through which employees and others can report wrongdoing without revealing who they are, and through which the responsible office can answer, without either side learning more than necessary. It runs on the organisation's own server. NexonAI runs nothing and has no access."),
 ("p","Note on the name: the name is a working name. A trademark search and legal advice are pending before public use.")]),
("How unpruuf works (short)",[("p","unpruuf Compliance is built on the unpruuf system: a reporter leaves a message in a sealed package on the organisation's own server, the officer picks it up and answers the same way. Nobody connects directly to anybody, there are no accounts, and what is not picked up is gone after at most 24 hours. The full explanation is in the document \"How unpruuf works\".")]),
("What you get ready-made from us",[("b",["The legal deadlines are built in: confirmation of receipt within 7 days, feedback to the reporter within 3 months (EU Directive 2019/1937, Art. 9).","A receipt is sent to the reporter automatically.","Every case receives a case number.","One QR code for the whole organisation that you can put on the intranet, a poster or the website.","A dashboard for the responsible officer, in Romanian and English, showing cases, status and deadlines.","The case file is stored encrypted on the officer's computer.","Start and install scripts for Windows."])]),
("What the reporter does",[("b",["Scans the organisation's QR code with the reporter app (Android).","Writes the report. No name, no number, no e-mail.","Receives the case number and the receipt.","Can read the officer's answers and reply, as long as the app keeps the case. Answers must be picked up within the time the packages live (at most 24 hours)."])]),
("What the officer does",[("b",["Starts the officer application on the work laptop and opens the dashboard.","Sees new reports, deadlines and open cases.","Replies to the reporter, sets the status, closes the case.","Keeps the case files only on that laptop."])]),
("What the organisation decides",[("b",["Who the officer is and where the officer application runs.","Which server is used and who operates it.","How long case files are kept, within the legal framework that applies to the organisation."])]),
("Legal context, carefully",[("b",["EU Directive 2019/1937 applies to companies with 50 or more employees.","In Romania, Law 361/2022 has applied since December 2022; for 50 to 249 employees since 17 December 2023.","There is no new deadline at the end of the year.","Whether anonymous reports must be accepted in Romania is currently unclear (an amendment has been proposed). We do not claim that they are mandatory.","unpruuf Compliance helps with these duties. It does not replace legal advice, and we do not call it \"compliant\"."])]),
("Data protection (GDPR)",[("b",["The architecture supports the principles of data minimisation, storage limitation and confidentiality (Art. 5, 25, 32).","The organisation is the controller (Art. 4(7)). NexonAI is normally not a processor (Art. 28) as long as it has no access to data. Your lawyer or data protection officer confirms this classification.","Where data is: server = sealed packages for at most 24 hours, no names or IPs; phone = local; officer laptop = case files, encrypted; licence = offline; website = no cookies."])]),
("Known limits",[("b",["No independent audit yet. Not certified.","The dashboard cannot yet delete or export a single case. We state this openly until it is built.","The Business app is English only; the unpruuf Compliance interfaces exist in Romanian and English.","The reporter must be able to reach the server; in networks that block the anonymity network, the connection assistant tries several routes. This has not been tested on a really blocked network.","Anonymity depends also on the reporter's behaviour (for example, content that identifies them)."])]),
("Suggested next steps for the team",[("b",["Book the independent audit.","Trademark search and legal advice on the name.","Build per-case delete and export.","Check the current text of the Romanian law before any statement on anonymous reports."])]),
])
put("2_safeline","RO","unpruuf Compliance","unpruuf Compliance · canal de raportare pentru companii și instituții · stare 12 oct. 2026",[
("Ce este",[("p","unpruuf Compliance este un canal prin care angajații și alte persoane pot semnala nereguli fără să își dezvăluie identitatea și prin care biroul responsabil poate răspunde, fără ca vreuna dintre părți să afle mai mult decât este necesar. Rulează pe serverul propriu al organizației. NexonAI nu operează nimic și nu are acces."),
 ("p","Notă privind numele: este o denumire de lucru. Înainte de utilizarea publică urmează o căutare de marcă și consultanță juridică.")]),
("Cum funcționează unpruuf (pe scurt)",[("p","unpruuf Compliance se bazează pe sistemul unpruuf: persoana care raportează lasă un mesaj într-un pachet sigilat pe serverul organizației, responsabilul îl ridică și răspunde pe aceeași cale. Nimeni nu se conectează direct la nimeni, nu există conturi, iar ce nu este ridicat dispare după cel mult 24 de ore. Explicația completă se află în documentul „Cum funcționează unpruuf”.")]),
("Ce primiți gata făcut de la noi",[("b",["Termenele legale sunt integrate: confirmarea primirii în 7 zile, feedback către persoana care raportează în 3 luni (Directiva UE 2019/1937, art. 9).","O confirmare de primire este trimisă automat.","Fiecare caz primește un număr de caz.","Un singur cod QR pentru toată organizația, pe care îl puteți pune pe intranet, pe un afiș sau pe site.","Un tablou de bord pentru responsabil, în română și engleză, cu cazuri, stare și termene.","Dosarul cazului este stocat criptat pe calculatorul responsabilului.","Scripturi de instalare și pornire pentru Windows."])]),
("Ce face persoana care raportează",[("b",["Scanează codul QR al organizației cu aplicația de raportare (Android).","Scrie sesizarea. Fără nume, fără număr, fără e-mail.","Primește numărul de caz și confirmarea.","Poate citi răspunsurile responsabilului și poate răspunde, cât timp aplicația păstrează cazul. Răspunsurile trebuie ridicate în timpul cât trăiesc pachetele (cel mult 24 de ore)."])]),
("Ce face responsabilul",[("b",["Pornește aplicația pe laptopul de serviciu și deschide tabloul de bord.","Vede sesizările noi, termenele și cazurile deschise.","Răspunde, stabilește starea, închide cazul.","Păstrează dosarele doar pe acel laptop."])]),
("Ce decide organizația",[("b",["Cine este responsabilul și unde rulează aplicația acestuia.","Ce server se folosește și cine îl operează.","Cât timp se păstrează dosarele, în cadrul legal aplicabil organizației."])]),
("Context juridic, cu grijă",[("b",["Directiva UE 2019/1937 se aplică companiilor cu cel puțin 50 de angajați.","În România, Legea 361/2022 se aplică din decembrie 2022; pentru 50–249 de angajați, din 17 decembrie 2023.","Nu există un termen nou la sfârșitul anului.","Dacă sesizările anonime trebuie acceptate în România este în prezent neclar (a fost propusă o modificare). Nu pretindem că sunt obligatorii.","unpruuf Compliance ajută la aceste obligații. Nu înlocuiește consultanța juridică și nu îl numim „conform”."])]),
("Protecția datelor (GDPR)",[("b",["Arhitectura sprijină principiile minimizării datelor, limitării stocării și confidențialității (art. 5, 25, 32).","Organizația este operator (art. 4 pct. 7). NexonAI nu este, în mod normal, persoană împuternicită (art. 28), atât timp cât nu are acces la date. Încadrarea o confirmă avocatul sau responsabilul cu protecția datelor.","Unde se află datele: server = pachete sigilate cel mult 24 de ore, fără nume sau IP-uri; telefon = local; laptopul responsabilului = dosare criptate; licență = offline; site = fără cookie-uri."])]),
("Limite cunoscute",[("b",["Încă fără audit independent. Necertificat.","Tabloul de bord nu poate încă șterge sau exporta un singur caz. Spunem asta deschis până când este construit.","Aplicația Business este doar în engleză; interfețele unpruuf Compliance există în română și engleză.","Persoana care raportează trebuie să poată ajunge la server; în rețelele care blochează rețeaua de anonimitate, asistentul de conexiune încearcă mai multe căi. Nu a fost testat într-o rețea blocată real.","Anonimatul depinde și de comportamentul celui care raportează (de exemplu, conținut care îl identifică)."])]),
("Pași propuși pentru echipă",[("b",["Programarea auditului independent.","Căutare de marcă și consultanță juridică pentru nume.","Construirea ștergerii și exportului pe caz.","Verificarea textului actual al legii românești înainte de orice afirmație despre sesizările anonime."])]),
])
put("2_safeline","DE","unpruuf Compliance","unpruuf Compliance · Meldekanal für Firmen und Institutionen · Stand 12.10.2026",[
("Was es ist",[("p","unpruuf Compliance ist ein Kanal, über den Beschäftigte und andere Missstände melden können, ohne sich zu offenbaren, und über den die Meldestelle antworten kann, ohne dass eine Seite mehr erfährt als nötig. Es läuft auf dem eigenen Server der Organisation. NexonAI betreibt nichts und hat keinen Zugriff."),
 ("p","Hinweis zum Namen: Arbeitsname. Vor der öffentlichen Nutzung stehen Markenrecherche und Jurist an (der Name „unpruuf Compliance“ ist bei einer bekannten Open-Source-Firewall belegt).")]),
("Wie unpruuf funktioniert (kurz)",[("p","unpruuf Compliance baut auf dem System unpruuf auf: Die meldende Person legt eine Nachricht als versiegeltes Paket auf dem Server der Organisation ab, die Meldestelle holt sie ab und antwortet auf demselben Weg. Niemand verbindet sich direkt mit jemandem, es gibt keine Konten, und was nicht abgeholt wird, ist nach höchstens 24 Stunden weg. Die volle Erklärung steht im Dokument „Wie unpruuf funktioniert“.")]),
("Was fertig von uns kommt",[("b",["Die gesetzlichen Fristen sind eingebaut: Eingangsbestätigung binnen 7 Tagen, Rückmeldung an die meldende Person binnen 3 Monaten (EU-Richtlinie 2019/1937, Art. 9).","Eine Eingangsbestätigung geht automatisch an die meldende Person.","Jeder Fall bekommt eine Fallnummer.","Ein QR-Code für die ganze Organisation: Intranet, Aushang oder Webseite.","Ein Dashboard für die Meldestelle, auf Rumänisch und Englisch, mit Fällen, Status und Fristen.","Die Falldatei liegt verschlüsselt auf dem Rechner der Meldestelle.","Install- und Start-Skripte für Windows."])]),
("Was die meldende Person tut",[("b",["Scannt den QR-Code der Organisation mit der Reporter-App (Android).","Schreibt die Meldung. Kein Name, keine Nummer, keine E-Mail.","Erhält Fallnummer und Eingangsbestätigung.","Kann die Antworten der Meldestelle lesen und antworten, solange die App den Fall hält. Antworten müssen innerhalb der Lebensdauer der Pakete abgeholt werden (höchstens 24 Stunden)."])]),
("Was die Meldestelle tut",[("b",["Startet die Officer-Anwendung auf dem Dienstlaptop und öffnet das Dashboard.","Sieht neue Meldungen, Fristen und offene Fälle.","Antwortet, setzt den Status, schließt den Fall.","Hält die Falldateien nur auf diesem Laptop."])]),
("Was die Organisation entscheidet",[("b",["Wer die Meldestelle ist und wo ihre Anwendung läuft.","Welcher Server genutzt wird und wer ihn betreibt.","Wie lange Falldateien aufbewahrt werden, im rechtlichen Rahmen der Organisation."])]),
("Rechtlicher Rahmen, vorsichtig",[("b",["Die EU-Richtlinie 2019/1937 gilt für Unternehmen ab 50 Beschäftigten.","In Rumänien gilt das Gesetz 361/2022 seit Dezember 2022; für 50 bis 249 Beschäftigte seit 17.12.2023.","Es gibt keine neue Frist zum Jahresende.","Ob anonyme Meldungen in Rumänien angenommen werden müssen, ist derzeit ungeklärt (Änderungsantrag). Wir behaupten nicht, dass sie vorgeschrieben sind.","unpruuf Compliance hilft bei diesen Pflichten. Es ersetzt keine Rechtsberatung, und wir nennen es nicht „konform“."])]),
("Datenschutz (DSGVO)",[("b",["Die Architektur unterstützt die Prinzipien Datenminimierung, Speicherbegrenzung und Vertraulichkeit (Art. 5, 25, 32).","Die Organisation ist Verantwortliche (Art. 4 Nr. 7). NexonAI ist normalerweise nicht Auftragsverarbeiter (Art. 28), solange kein Datenzugriff besteht. Die Einordnung bestätigt ein Jurist oder der Datenschutzbeauftragte.","Datenlandkarte: Server = versiegelte Pakete höchstens 24 h, keine Namen/IPs; Telefon = lokal; Officer-Laptop = Falldateien verschlüsselt; Lizenz = offline; Website = keine Cookies."])]),
("Bekannte Grenzen",[("b",["Noch kein unabhängiges Audit. Nicht zertifiziert.","Das Dashboard kann einen einzelnen Fall noch nicht löschen oder exportieren. Wir nennen das offen, bis es gebaut ist.","Die Business-App ist nur Englisch; die Compliance-Oberflächen gibt es auf Rumänisch und Englisch.","Die meldende Person muss den Server erreichen; in Netzen, die das Anonymisierungsnetz sperren, probiert der Verbindungsassistent mehrere Wege. In einem wirklich gesperrten Netz nicht getestet.","Anonymität hängt auch vom Verhalten der meldenden Person ab (zum Beispiel identifizierende Inhalte)."])]),
("Vorschläge für das Team",[("b",["Unabhängiges Audit buchen.","Markenrecherche und Jurist zum Namen.","Fall löschen und exportieren bauen.","Vor jeder Aussage zu anonymen Meldungen den aktuellen Gesetzestext in Rumänien prüfen."])]),
])

# ---------------- 3 PRESS ----------------
put("3_safeline_Press","EN","unpruuf Press","unpruuf Press · tip channel for journalists and editorial teams · PILOT VERSION · status 12 Oct 2026",[
("What it is",[("p","unpruuf Press lets a journalist put a QR code on their page or in their publication. A source scans it and writes directly, without account, name or phone number. The tips arrive on the journalist's own server and nowhere else. It is the same system as unpruuf Compliance, with different settings for keeping and deleting."),
 ("p","Status: pilot version. It has not been tested with a real source and not through a real anonymity network under field conditions.")]),
("How unpruuf works (short)",[("p","The source leaves a sealed package on the journalist's server; the journalist picks it up and answers the same way. There are no accounts, no direct connection between the two, and whatever is not picked up is gone after at most 24 hours. Details are in \"How unpruuf works\".")]),
("What you get ready-made from us",[("b",["A press edition of the officer application, started with its own start script.","A retention setting: the journalist decides how many hours or days tips are kept. The data is kept as long as the journalist wants.","Deleting a tip really removes it (the store is overwritten and compacted).","A warning at pickup: packets that are not picked up within 24 hours are gone.","A QR code as PNG file and as a ready HTML snippet to paste into a website.","No legal deadlines. These belong to the compliance product, not to press work.","The reporter app for sources is free. An Android build of the reporter app exists in a Press version, with English and Romanian texts."])]),
("What the source does",[("b",["Scans the QR code with the free app (or follows the link on the page).","Writes the tip.","Reads the journalist's answers within the time the packages live."])]),
("What the journalist does",[("b",["Starts the Press edition on the laptop and opens the dashboard.","Publishes the QR code on the site or in print.","Reads tips, replies, deletes what should not be kept.","Sets how long tips are retained."])]),
("Important for sources and journalists",[("b",["A browser alone does not protect the source's network address. We recommend that the source uses the app, or at least the Tor Browser.","A source who is known to be in contact can still be identified by other means (for example by what they write). The system hides the channel, not the content of the story.","Tips must be picked up in time. Whatever lies longer than 24 hours is gone."])]),
("Known limits",[("b",["Pilot. Not tested with a real source.","Not audited, not certified.","No group chats and no push notifications by design.","A journalist who must keep material for legal reasons has to export it themselves; there is no case export in the dashboard yet.","Not a replacement for operational security training."])]),
("Suggested next steps for the team",[("b",["Run a pilot with one editorial team and a test source.","Independent audit.","Case export and delete per tip with a confirmation screen.","Review of claims by a press-freedom or legal organisation."])]),
])
put("3_safeline_Press","RO","unpruuf Press","unpruuf Press · canal pentru sesizări destinat jurnaliștilor și redacțiilor · VERSIUNE PILOT · stare 12 oct. 2026",[
("Ce este",[("p","unpruuf Press permite unui jurnalist să pună un cod QR pe pagina sa sau în publicația sa. O sursă îl scanează și scrie direct, fără cont, nume sau număr de telefon. Sesizările ajung pe serverul propriu al jurnalistului și nicăieri altundeva. Este același sistem ca unpruuf Compliance, cu alte setări pentru păstrare și ștergere."),
 ("p","Stare: versiune pilot. Nu a fost testată cu o sursă reală și nici printr-o rețea de anonimitate în condiții reale.")]),
("Cum funcționează unpruuf (pe scurt)",[("p","Sursa lasă un pachet sigilat pe serverul jurnalistului; jurnalistul îl ridică și răspunde pe aceeași cale. Nu există conturi, nu există conexiune directă între cei doi, iar ce nu este ridicat dispare după cel mult 24 de ore. Detalii în „Cum funcționează unpruuf”.")]),
("Ce primiți gata făcut de la noi",[("b",["O ediție Press a aplicației responsabilului, pornită cu propriul script de pornire.","Un parametru de păstrare: jurnalistul decide câte ore sau zile se păstrează sesizările. Datele se păstrează cât dorește jurnalistul.","Ștergerea unei sesizări o elimină cu adevărat (stocul este suprascris și compactat).","Un avertisment la ridicare: pachetele neridicate în 24 de ore dispar.","Un cod QR ca fișier PNG și ca fragment HTML gata de lipit într-un site.","Fără termene legale. Acestea țin de produsul de conformitate, nu de munca jurnalistică.","Aplicația pentru surse este gratuită. Există o versiune Android Press a aplicației de raportare, cu texte în engleză și română."])]),
("Ce face sursa",[("b",["Scanează codul QR cu aplicația gratuită (sau urmează linkul de pe pagină).","Scrie sesizarea.","Citește răspunsurile jurnalistului în timpul cât trăiesc pachetele."])]),
("Ce face jurnalistul",[("b",["Pornește ediția Press pe laptop și deschide tabloul de bord.","Publică codul QR pe site sau în tipar.","Citește sesizările, răspunde, șterge ce nu trebuie păstrat.","Stabilește cât timp se păstrează sesizările."])]),
("Important pentru surse și jurnaliști",[("b",["Un browser singur nu protejează adresa de rețea a sursei. Recomandăm ca sursa să folosească aplicația sau cel puțin Tor Browser.","O sursă despre care se știe că este în contact poate fi totuși identificată prin alte mijloace (de exemplu prin ce scrie). Sistemul ascunde canalul, nu conținutul poveștii.","Sesizările trebuie ridicate la timp. Ce stă mai mult de 24 de ore dispare."])]),
("Limite cunoscute",[("b",["Pilot. Netestat cu o sursă reală.","Neauditat, necertificat.","Fără conversații de grup și fără notificări push, intenționat.","Un jurnalist care trebuie să păstreze material din motive legale trebuie să îl exporte singur; încă nu există export de caz în tabloul de bord.","Nu înlocuiește instruirea în securitate operațională."])]),
("Pași propuși pentru echipă",[("b",["Un pilot cu o redacție și o sursă de test.","Audit independent.","Export și ștergere pe sesizare, cu ecran de confirmare.","Verificarea afirmațiilor de către o organizație pentru libertatea presei sau de către un jurist."])]),
])
put("3_safeline_Press","DE","unpruuf Press","unpruuf Press · Hinweiskanal für Journalisten und Redaktionen · PILOTVERSION · Stand 12.10.2026",[
("Was es ist",[("p","Mit unpruuf Press stellt ein Journalist einen QR-Code auf seine Seite oder in seine Publikation. Eine Quelle scannt ihn und schreibt direkt, ohne Konto, Namen oder Telefonnummer. Die Hinweise landen auf dem eigenen Server des Journalisten und nirgends sonst. Es ist dasselbe System wie unpruuf Compliance, mit anderen Einstellungen für Speichern und Löschen."),
 ("p","Stand: Pilotversion. Nicht mit einer echten Quelle getestet und nicht durch ein echtes Anonymisierungsnetz unter Feldbedingungen.")]),
("Wie unpruuf funktioniert (kurz)",[("p","Die Quelle legt ein versiegeltes Paket auf dem Server des Journalisten ab; der Journalist holt es ab und antwortet auf demselben Weg. Keine Konten, keine direkte Verbindung zwischen beiden, und was nicht abgeholt wird, ist nach höchstens 24 Stunden weg. Details in „Wie unpruuf funktioniert“.")]),
("Was fertig von uns kommt",[("b",["Eine Press-Edition der Officer-Anwendung mit eigenem Start-Skript.","Eine Aufbewahrungs-Einstellung: Der Journalist entscheidet, wie viele Stunden oder Tage Hinweise bleiben. Die Daten bleiben, so lange er will.","Löschen eines Hinweises entfernt ihn wirklich (Speicher wird überschrieben und verdichtet).","Eine Warnung beim Abholen: Pakete, die nicht binnen 24 Stunden abgeholt werden, sind weg.","Ein QR-Code als PNG-Datei und als fertiger HTML-Schnipsel zum Einfügen in eine Webseite.","Keine gesetzlichen Fristen. Die gehören zum Compliance-Produkt, nicht zur Pressearbeit.","Die Reporter-App für Quellen ist kostenlos. Es gibt einen Android-Build der Reporter-App als Press-Version, mit englischen und rumänischen Texten."])]),
("Was die Quelle tut",[("b",["Scannt den QR-Code mit der kostenlosen App (oder folgt dem Link auf der Seite).","Schreibt den Hinweis.","Liest die Antworten des Journalisten innerhalb der Lebensdauer der Pakete."])]),
("Was der Journalist tut",[("b",["Startet die Press-Edition auf dem Laptop und öffnet das Dashboard.","Veröffentlicht den QR-Code auf der Seite oder im Druck.","Liest Hinweise, antwortet, löscht, was nicht bleiben soll.","Stellt ein, wie lange Hinweise aufbewahrt werden."])]),
("Wichtig für Quellen und Journalisten",[("b",["Ein Browser allein schützt die Netzadresse der Quelle nicht. Wir empfehlen die App oder mindestens den Tor Browser.","Eine Quelle, von der bekannt ist, dass sie Kontakt hat, kann auf anderen Wegen erkannt werden (zum Beispiel an dem, was sie schreibt). Das System verbirgt den Kanal, nicht den Inhalt der Geschichte.","Hinweise müssen rechtzeitig abgeholt werden. Was länger als 24 Stunden liegt, ist weg."])]),
("Bekannte Grenzen",[("b",["Pilot. Nicht mit echter Quelle getestet.","Nicht auditiert, nicht zertifiziert.","Keine Gruppenchats und keine Push-Benachrichtigungen, bewusst.","Wer Material aus rechtlichen Gründen aufbewahren muss, muss es selbst exportieren; einen Fall-Export im Dashboard gibt es noch nicht.","Kein Ersatz für eine Schulung in operativer Sicherheit."])]),
("Vorschläge für das Team",[("b",["Pilot mit einer Redaktion und einer Testquelle.","Unabhängiges Audit.","Export und Löschen pro Hinweis mit Bestätigung.","Prüfung der Aussagen durch eine Pressefreiheits-Organisation oder einen Juristen."])]),
])
